def test_withdrawal_pages_use_contiguous_uint64_strings() -> None:
    """大于安全整数的序号不舍入，乱序 / 缺口 / 最大值回报均不能当连续页。"""
    after = 2**53 + 1
    entry = {"sequence": str(after + 1), "target": target().model_dump(), "withdrawal_epoch": 1, "reason": "deleted"}
    batch = WithdrawalBatch(after=str(after), authority_frontier=str(after + 2), entries=[entry])
    assert batch.entries[0].sequence == str(after + 1)
    for change in ({"entries": [{**entry, "sequence": str(after + 2)}]}, {"entries": []}, {"after": "01"}, {"after": str(2**64)}, {"authority_frontier": str(after - 1)}):
        with pytest.raises(ValidationError):
            WithdrawalBatch(**{**batch.model_dump(), **change})


